#!/bin/bash
# orca-5 (orca 5.0.4) on atlas:vanilla; generated by `rag-drg servers submit` from servers.yaml
# HTCondor job script, run by submit.sub (4 cores, 4 GB requested there);
# submit with: chmod u+x job.sh && condor_submit submit.sub
# expected run time 12:00:00; HTCondor has no walltime request, and the pool holds jobs running
# longer than 72:00:00 (vanilla in servers.yaml)

WORKDIR="${_CONDOR_JOB_IWD:-$PWD}"
JOBID="${CONDOR_JOBID:-$$}"
cd "$WORKDIR"

# --- orca-5: absolute paths, no environment modules ---
export PATH="/Local/ce_dana/orca_5_0_4_linux_x86-64_shared_openmpi411:/Local/ce_dana/openmpi-4.1.1/bin:$PATH"
export LD_LIBRARY_PATH="/Local/ce_dana/orca_5_0_4_linux_x86-64_shared_openmpi411:/Local/ce_dana/openmpi-4.1.1/lib:$LD_LIBRARY_PATH"
ORCA_BIN=/Local/ce_dana/orca_5_0_4_linux_x86-64_shared_openmpi411/orca

# --- per-job scratch ---
SCRATCH="/storage/ce_dana/$USER/scratch/$JOBID"
mkdir -p "$SCRATCH"

# on exit, also after a walltime kill or scancel/qdel/condor_rm (SIGTERM): copy back and clean up
cleanup() {
    # copy back everything useful, then clean scratch
    if cd "$SCRATCH" 2>/dev/null; then
        cp -f *.gbw *.hess *.xyz *.engrad *property.txt "$WORKDIR"/ 2>/dev/null
    fi
    cd "$WORKDIR" || true
    rm -rf "$SCRATCH"
}
trap cleanup EXIT
trap 'exit 143' TERM INT

INPUT="H2O_sp.inp"
cp "$WORKDIR/H2O_sp.inp" "$SCRATCH"/
# for MORead / InHess also copy: cp "$WORKDIR"/*.gbw "$WORKDIR"/*.hess "$SCRATCH"/ 2>/dev/null
cd "$SCRATCH"
"$ORCA_BIN" "$INPUT" > "$WORKDIR/H2O_sp.out"
